840: inline std::vector<std::string> string_split<std::string>(const std::string & str, char delim)
841: {
842:     std::vector<std::string> parts;
843:     size_t begin_pos = 0;
844:     size_t delim_pos = str.find(delim);
845:     while (delim_pos != std::string::npos) {
846:         std::string part = str.substr(begin_pos, delim_pos - begin_pos);
847:         parts.emplace_back(part);
848:         begin_pos = delim_pos + 1;
849:         delim_pos = str.find(delim, begin_pos);
850:     }
851:     parts.emplace_back(str.substr(begin_pos));
852:     return parts;
